package com.gmail.manhle240406.project.adoption;
import android.app.Application;import androidx.lifecycle.*;import com.gmail.manhle240406.project.AniloveApplication;import com.gmail.manhle240406.project.foundation.*;import com.google.firebase.functions.*;import java.util.*;
/** Form/care stays session RAM through rotation; saved state contains only receipt routing IDs. */
public final class AdoptionFlowModel extends AndroidViewModel {
 public final MutableLiveData<Long> changes=new MutableLiveData<>(0L);public boolean managementOrigin;public String managementRole="applicant";public final Map<String,Integer> managementPages=new HashMap<>();public final Map<String,ArrayList<String>> managementCursors=new HashMap<>();public String page="workspace",petId,listingId,applicationId,reservationId,error="",notice="",pendingFamily;public boolean busy,lost;public int step;public Map<String,Object> workspaceData=new HashMap<>(),extras=new HashMap<>(),data=new HashMap<>(),pet=new HashMap<>(),fields=map("title","","description","","regionCode",null,"offerType","adoption","mediaRefs",new ArrayList<>()),care=PetCareContract.unknown();public String medication="";public long careVersion,contentVersion,controlVersion,draftVersion;public String careDigest="";public String draftId=UUID.randomUUID().toString();public String lastReadOperation;public Map<String,Object> lastReadInput=new HashMap<>(),reviewQueueData=new HashMap<>(),applicationsData=new HashMap<>();private long workspaceAt;private boolean workspaceDirty=true;private long generation,event;private final SessionGateway sessions;public final SessionEpoch.Ticket ticket;private final Runnable invalidated=this::clear;private final SavedStateHandle saved;private String pendingOperation;private Map<String,Object> pendingInput;private Runnable pendingSuccess;private java.util.function.Consumer<String> pendingFailure;
 public AdoptionFlowModel(Application app,SavedStateHandle state){super(app);saved=state;sessions=((AniloveApplication)app).foundation().sessions;ticket=sessions==null?null:sessions.capture();if(sessions!=null)sessions.onInvalidated(invalidated);if(ticket==null||ticket.uid==null){lost=true;return;}String owner=saved.get("adoption_owner");if(owner!=null&&!owner.equals(ticket.uid))saved.remove("adoption_pending");if(saved.contains("adoption_pending")){pendingOperation=saved.get("adoption_family");error="unknown_outcome";}}
 public static Map<String,Object> map(Object... pairs){Map<String,Object> m=new HashMap<>();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
 @SuppressWarnings("unchecked") public static Map<String,Object> object(Object v){return v instanceof Map?(Map<String,Object>)v:new HashMap<>();}
 @SuppressWarnings("unchecked") public static List<Map<String,Object>> rows(Object v){return v instanceof List?(List<Map<String,Object>>)v:Collections.emptyList();}
 public static long number(Object v){return v instanceof Number?((Number)v).longValue():0;}
 public void changed(){changes.setValue(++event);}private boolean current(long g){return !lost&&generation==g&&sessions.current(ticket);}
 public boolean uncertain(){return saved.contains("adoption_pending");}
 private void clear(){generation++;lost=true;busy=false;data.clear();workspaceData.clear();reviewQueueData.clear();applicationsData.clear();extras.clear();pet.clear();fields.clear();care=PetCareContract.unknown();medication="";pendingInput=null;pendingSuccess=null;pendingFailure=null;notice="";for(String k:new String[]{"adoption_owner","adoption_pending","adoption_family","adoption_command"})saved.remove(k);changed();}
 public void read(String operation,Map<String,Object> input,java.util.function.Consumer<Map<String,Object>> done){if(busy||lost)return;busy=true;error="";long g=generation;changed();AdoptionApi.call(operation,input).addOnCompleteListener(t->{if(!current(g))return;busy=false;if(t.isSuccessful())done.accept(t.getResult());else error=code(t.getException());changed();});}
 public void load(String page,String operation,Map<String,Object> input){this.page=page;lastReadOperation=operation;lastReadInput=new HashMap<>(input);read(operation,input,r->{data=r;if(operation.equals("workspace"))workspaceData=r;if(operation.equals("reviewQueue"))reviewQueueData=r;if(operation.equals("applications"))applicationsData=r;});}
 public void write(String operation,Map<String,Object> input,Runnable success){write(operation,input,success,null);}
 public void write(String operation,Map<String,Object> input,Runnable success,java.util.function.Consumer<String> failure){if(busy||lost||uncertain())return;pendingInput=new HashMap<>(input);pendingInput.put("operationId",UUID.randomUUID().toString());pendingOperation=operation;pendingSuccess=success;pendingFailure=failure;notice="";saved.set("adoption_owner",ticket.uid);saved.set("adoption_pending",pendingInput.get("operationId"));saved.set("adoption_family",operation);saved.set("adoption_command",input.get("command"));send();}
 private void send(){if(busy||lost||pendingInput==null)return;busy=true;error="";long g=generation;changed();AdoptionApi.call(pendingOperation,pendingInput).addOnCompleteListener(t->{if(!current(g))return;busy=false;if(t.isSuccessful()){data=t.getResult();workspaceDirty=true;Runnable done=pendingSuccess;finishPending();if(done!=null)done.run();}else{String code=code(t.getException());if(code.equals("unknown_outcome"))error=code;else{java.util.function.Consumer<String> failed=pendingFailure;finishPending();error=code;if(failed!=null)failed.accept(code);}}changed();});}
 public void reconcile(){if(busy||lost||!uncertain())return;String id=saved.get("adoption_pending"),command=saved.get("adoption_command");read("receipt",map("operationId",id,"family",pendingOperation,"command",command),r->{if(r.get("receipt")!=null){data=object(object(r.get("receipt")).get("result"));Runnable success=pendingSuccess;finishPending();if(success!=null)success.run();else workspace();}else error="receipt_pending";});}
 public void retrySame(){if(!busy&&uncertain()&&pendingInput!=null)send();}
 private void finishPending(){saved.remove("adoption_pending");saved.remove("adoption_family");saved.remove("adoption_command");pendingInput=null;pendingSuccess=null;pendingFailure=null;pendingOperation=null;error="";}
 private String code(Exception e){Throwable p=e;while(p!=null){if(p instanceof FirebaseFunctionsException){FirebaseFunctionsException f=(FirebaseFunctionsException)p;if(Arrays.asList(FirebaseFunctionsException.Code.UNAVAILABLE,FirebaseFunctionsException.Code.DEADLINE_EXCEEDED,FirebaseFunctionsException.Code.INTERNAL).contains(f.getCode()))return "unknown_outcome";return f.getMessage()==null?"unavailable":f.getMessage();}p=p.getCause();}return "unknown_outcome";}
 public void workspace(){workspace(false);}
 public void workspace(boolean force){notice="";page="workspace";if(!force&&!workspaceDirty&&!workspaceData.isEmpty()&&android.os.SystemClock.elapsedRealtime()-workspaceAt<60_000){data=workspaceData;changed();return;}read("workspace",map(),r->{data=r;workspaceData=r;workspaceAt=android.os.SystemClock.elapsedRealtime();workspaceDirty=false;});}
 public void choosePet(String id){notice="";petId=id;read("pet",map("petId",id),r->{pet=r;Map<String,Object> cr=object(r.get("revision"));care=cr.get("payload") instanceof Map?new HashMap<>(object(cr.get("payload"))):PetCareContract.unknown();careVersion=number(object(r.get("care")).get("currentCareVersion"));careDigest=String.valueOf(cr.getOrDefault("digest",""));medication=String.valueOf(object(r.get("privateCare")).getOrDefault("medicationNotes",""));step=1;page="compose";});}
 public void refreshClaim(){read("pet",map("petId",petId),r->{pet=r;if(!"submitted".equals(object(r.get("claim")).get("reviewState")))notice="";});}
 public void submitClaim(){Map<String,Object> claim=object(pet.get("claim"));write("submitClaim",map("petId",petId,"expectedClaimVersion",claim.get("claimVersion"),"expectedIdentityVersion",object(pet.get("pet")).get("identityVersion")),()->{notice="claim_submitted";refreshClaim();});}
 public void submitOffer(){String id=listingId==null?draftId:listingId;write("saveOffer",map("listingId",id,"petId",petId,"expectedContentVersion",contentVersion,"expectedControlVersion",controlVersion,"careVersion",careVersion,"careDigest",careDigest,"fields",fields),()->{listingId=id;contentVersion=number(data.get("contentVersion"));page="offerStatus";write("submitReview",map("listingId",id,"contentVersion",contentVersion,"requestVersion",0),()->{notice="listing_submitted";offer(id);},code->read("offer",map("listingId",id),r->{data=r;String state=String.valueOf(object(r.get("review")).get("state"));boolean queued=Arrays.asList("queued","assigned").contains(state);error=queued?"":code;notice=queued?"listing_submitted":object(r.get("review")).isEmpty()?"saved_not_sent":"";}));});}
 public void offer(String id){listingId=id;load("offerStatus","offer",map("listingId",id));}
 public void saveCare(){PetCareContract.validate(care,medication,java.time.LocalDate.now(java.time.ZoneOffset.UTC));Map<String,Object> p=object(pet.get("pet"));write("care",map("petId",petId,"expectedCareVersion",careVersion,"expectedIdentityVersion",p.get("identityVersion"),"expectedCustodyVersion",p.get("custodyVersion"),"payload",care,"medicationNotes",medication),()->{careVersion=number(data.get("careVersion"));careDigest=String.valueOf(data.get("careDigest"));step=2;page="compose";});}
 @Override protected void onCleared(){if(sessions!=null)sessions.removeInvalidation(invalidated);clear();}
}
